    check(base_inputs['baseRuntimeDescriptorFile'] == COMMON and identity.sha(COMMON) == COMMON_SHA,
          'Publication base differs from the preserved common128 descriptor')
    common = read_json(COMMON)
    common_inputs = descriptor_files(common)
