    _, original = identity.original_identity()
    check(len(common_manifest) == 128 and common_manifest[1:] == original
          and common_manifest == read_json(common_inputs['classpathManifestFile'])
          and common_manifest[0]['files'] == 15 and common_manifest[0]['sha256'] == COMMON_PREFIX_SHA,
          'The fifteen common harness files or original127 runtime changed')
